INSERT INTO athletes (id, name, first_name, coach_name, headline, sport, photo_url, hero_url, badges, bio_text, bio_status, bio_audio_key, bio_duration, paused, guard_topics, guard_decline, created_at) VALUES ('angela', 'Angela Ruggiero', 'Angela', 'Coach Angela', 'Olympic gold medalist · Hockey Hall of Fame', 'Hockey', 'https://billyatminyawns.github.io/strive/assets/angela1.webp', 'https://billyatminyawns.github.io/strive/assets/medals.jpg', '["4× Olympian","4 Olympic medals","IOC member 2010–18"]', 'Hey, I''m Angela. Four Olympics, a gold medal from Nagano, and a seat in the Hockey Hall of Fame — but honestly, defense taught me more than the podiums did. These days I serve on boards, work across the Olympic movement, and geek out on mindset, nutrition, and leadership. Everything you hear in here, I wrote or approved. Come say hi.', 'draft', '7c0bf31d878290d7e9214fb1330245afe153245d', 19.96, 0, 1, 1, 1790697600000) ON CONFLICT (id) DO UPDATE SET name = excluded.name, first_name = excluded.first_name, coach_name = excluded.coach_name, headline = excluded.headline, sport = excluded.sport, photo_url = excluded.photo_url, hero_url = excluded.hero_url, badges = excluded.badges;
INSERT OR IGNORE INTO invite_codes (code, athlete_id, active, created_at) VALUES ('ANGELA', 'angela', 1, 1790697600000);
INSERT OR IGNORE INTO drops (id, athlete_id, title, script, status, source, audio_key, duration, published_at, queue_pos, pinned, created_at) VALUES ('d_ang_drop-1', 'angela', 'Morning skate mindset', 'Morning. Quick thought before you hit the ice today. The morning skate isn''t about proving anything — it''s about telling your body the truth: we''re playing tonight. So pick one thing. One. Maybe it''s your first touch, maybe it''s talking louder on switches. Do it at game speed for twenty minutes and get off. Poise beats panic, and poise is built in the morning. Go have a day.', 'draft', 'Starter draft — edit it or redraft it', 'e0df4e0d8ecf0a6c1beb0e891e9cb373c5ce68ee', 23.85, NULL, NULL, 0, 1790697600000);
INSERT OR IGNORE INTO drops (id, athlete_id, title, script, status, source, audio_key, duration, published_at, queue_pos, pinned, created_at) VALUES ('d_ang_drop-2', 'angela', 'Road trip Q&A', 'Road trip questions, rapid fire. Best road habit? Unpack fully, even for one night — chaos in the room becomes chaos on the ice. Roommates? Pick the one who sleeps. Food? Eat what you know, not what''s exciting. And the big one — homesickness. It''s not weakness, it''s a signal you have something worth missing. Call home, then close the loop and be where your feet are.', 'draft', 'Starter draft — edit it or redraft it', '12b322306bddf4b1caeacb526209aaf72da700b5', 22.67, NULL, NULL, 0, 1790697600001);
INSERT OR IGNORE INTO drops (id, athlete_id, title, script, status, source, audio_key, duration, published_at, queue_pos, pinned, created_at) VALUES ('d_ang_drop-3', 'angela', 'Gold medal morning', 'People ask what the morning of the gold medal game felt like. Honestly? Quiet. We''d done the loud part for four years. I remember tying my skates and thinking — nothing new today. Same tape job, same warm-up, same first shift plan. Big moments don''t want more from you. They want exactly what you''ve already built, delivered on time.', 'draft', 'Starter draft — edit it or redraft it', '082265cb1f2d07ab4aba26c676d263d350ba3c3c', 20.87, NULL, NULL, 0, 1790697600002);
INSERT OR IGNORE INTO drops (id, athlete_id, title, script, status, source, audio_key, duration, published_at, queue_pos, pinned, created_at) VALUES ('d_ang_dd-1', 'angela', 'Why I loved the 4 AM practices', 'Everyone hates the 4 AM practice story until they need it. Empty rink, cold air, nobody watching — that''s where you find out if you love the work or the applause. I learned to love the work. The applause got loud later on its own.', 'draft', 'Starter draft — edit it or redraft it', 'a70a1c06fc9fe9d24f28b9d3721d0ec80f0e256a', 13.14, NULL, NULL, 0, 1790697600003);
INSERT OR IGNORE INTO drops (id, athlete_id, title, script, status, source, audio_key, duration, published_at, queue_pos, pinned, created_at) VALUES ('d_ang_dd-2', 'angela', 'Reading a locker room in 60 seconds', 'Walk in and count who''s looking at the floor. A quiet room isn''t a focused room — focused rooms hum. If the floor-lookers outnumber the hummers, your first job isn''t tactics. It''s getting one honest laugh before puck drop.', 'draft', 'Starter draft — edit it or redraft it', 'cac367e3d2056131555034cd64300e1027bb70cd', 15.88, NULL, NULL, 0, 1790697600004);
INSERT OR IGNORE INTO drops (id, athlete_id, title, script, status, source, audio_key, duration, published_at, queue_pos, pinned, created_at) VALUES ('d_ang_dd-3', 'angela', 'The gear superstition I''ll admit to', 'Left skate first, always. Not because it works — because deciding it works gave my brain one less thing to negotiate at six PM on game day. Superstitions aren''t magic. They''re pre-made decisions. Make yours boring, and keep them.', 'draft', 'Starter draft — edit it or redraft it', 'b650968ae8c5923ccd06241346792a6170a73637', 17.06, NULL, NULL, 0, 1790697600005);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_kb-reset', 'angela', NULL, 'starter', 'How did you reset after a bad shift in big games?', 'pending', 'Short memory, long habits. I gave myself one length of the bench to be frustrated — then eyes up, next play. The reset is a skill you train, not a mood you wait for.', 'starter', 0, '["reset","bad shift","mistake","bounce back from a bad"]', 0, 1790697600000);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_kb-nerves', 'angela', NULL, 'starter', 'How do I handle pre-game nerves?', 'pending', 'Nerves mean it matters. The night before gold in Nagano I barely slept — so I stopped chasing calm and built a routine I could do scared: same warm-up, same first touch, one cue word. Borrow mine until you build yours.', 'starter', 0, '["nerve","nervous","anxious","anxiety","scared","pre-game","pregame","pressure"]', 0, 1790697600001);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_kb-gap', 'angela', NULL, 'starter', 'Best drills for gap control on a small rink?', 'pending', 'A small rink is a gift — less ice to defend if your feet are honest. Work two-touch angling walls, stick on the puck side, and time your gap off their second stride, not their first.', 'starter', 0, '["gap control","small rink","drill","angling"]', 0, 1790697600002);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_kb-routine', 'angela', NULL, 'starter', 'What''s your morning routine?', 'pending', 'Boring and repeatable. Up at six, ten minutes of mobility before coffee, and I write the day''s one hard thing on a sticky note. Champions aren''t morning people — they''re consistency people who happen to be awake.', 'starter', 0, '["morning routine","daily routine","start your day","wake up"]', 0, 1790697600003);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_kb-ioc', 'angela', NULL, 'starter', 'What have you done since hockey?', 'pending', 'Hockey was chapter one, not the whole book. I served on the IOC as an athlete rep, sat on boards, built companies, and kept collecting degrees along the way. Different rooms, same game: show up prepared, ask the honest question, do the boring work. The rink just taught me first.', 'starter', 0, '["the ioc","olympic committee","after hockey","since hockey","retire","board member","boardroom","businesses","executive","career after","life after"]', 0, 1790697600004);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_q-marcus', 'angela', NULL, 'starter', 'I''m 16 and just got cut from AAA. How do I come back from this?', 'pending', 'Getting cut stings because you care — good. I didn''t make every roster I tried out for either. Give yourself 48 hours to feel it, then get specific: ask the coach for the two things that kept you off the list, and build your summer around exactly those. The cut is feedback, not a verdict. Send me your plan in September — I mean it.', 'starter', 0, '["cut","roster","didn''t make","not make the team","tryout didn"]', 0, 1790697600005);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_q-priya', 'angela', NULL, 'starter', 'What do you eat on game day?', 'pending', 'Boring on purpose. Oatmeal at 8, pasta at noon, nothing new on game day — ever. The meal isn''t the performance, the routine is. Save the adventurous eating for the off-season, and drink more water than you think you need.', 'starter', 0, '["eat","nutrition","food","game day","diet","meal"]', 0, 1790697600006);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_q-dev', 'angela', NULL, 'starter', 'How do I captain teammates older than me?', 'pending', 'Titles don''t lead, standards do. Be first on the ice and last to blame, and never ask for anything you don''t visibly do yourself. Older teammates don''t follow your letter — they follow your consistency. Give it three weeks before you judge whether it''s working.', 'starter', 0, '["captain","older teammates","leadership","lead the team"]', 0, 1790697600007);
INSERT OR IGNORE INTO questions (id, athlete_id, user_id, kind, text, status, draft, draft_source, drafting, kb_keys, saved, created_at) VALUES ('q_ang_q-lena', 'angela', NULL, 'starter', 'Advice for my daughter''s first tryout?', 'pending', 'Tell her the tryout starts in the parking lot — how she carries her bag, how she greets the coach, how she listens in line. Skills get you noticed, but coachability gets you picked. And whatever happens: same dinner after, win or lose. That''s how she learns the tryout doesn''t define her.', 'starter', 0, '["first tryout","daughter","tryout advice"]', 0, 1790697600008);
INSERT INTO prompts (id, athlete_id, title, src, hint, sort) VALUES ('sp-nagano', 'angela', 'The night before Nagano', 'STARTER PROMPT', 'The night before the gold medal game: where you were, whether you slept, what was running through your head.', 0) ON CONFLICT (athlete_id, id) DO UPDATE SET title = excluded.title, src = excluded.src, hint = excluded.hint, sort = excluded.sort;
